# NEXUS 360 - Auditoria A02: PK, FK candidatas, regras de negocio e reconciliacoes (SQL)
# Uso: python3 -I a02_integridade.py <raiz> <db>
import sys, sqlite3, csv, json, os
raiz, dbp = sys.argv[1], sys.argv[2]
con = sqlite3.connect(dbp)
for _t,_c in [("fPedido","PedidoID"),("fItemPedido","PedidoID"),("fFaturamento","PedidoID"),("fEntrega","PedidoID"),("fContasReceber","PedidoID"),("dCliente","ClienteID"),("dProduto","ProdutoID"),("dCalendario","Data")]: con.execute(f"create index if not exists ix_{_t}_{_c} on {_t}({_c})")
q = lambda s: con.execute(s).fetchall()
R = {}
pks = {t: q(f'PRAGMA table_info("{t}")')[0][1] for (t,) in q("select name from sqlite_master where type='table'")}
R['pk'] = {t: q(f'select count(*)-count(distinct "{c}") + sum("{c}" is null) from "{t}"')[0][0] for t, c in pks.items()}
rels = list(csv.DictReader(open(os.path.join(raiz,'dados/NEXUS360/RELACIONAMENTOS.csv'), encoding='utf-8-sig')))
R['fk'] = []
for r in rels:
    o,co,d,cd = r['TabelaOrigem'],r['ColunaOrigem'],r['TabelaDestino'],r['ColunaDestino']
    orf = q(f'select count(*), count(distinct a."{co}") from "{o}" a left join "{d}" b on a."{co}"=b."{cd}" where a."{co}" is not null and b."{cd}" is null')[0]
    nulls = q(f'select sum("{co}" is null) from "{o}"')[0][0]
    dup_dest = q(f'select count(*)-count(distinct "{cd}") from "{d}"')[0][0]
    R['fk'].append({'rel': f'{o}[{co}] -> {d}[{cd}]', 'orfaos': orf[0], 'orfaos_distintos': orf[1], 'nulos_origem': nulls, 'dup_destino': dup_dest, 'obs': r['Observacao']})
C = {}
def chk(k, s): C[k] = q(s)
chk('faturas_por_pedido_max', 'select max(n) from (select count(*) n from fFaturamento group by PedidoID)')
chk('faturaid_igual_pedidoid', 'select sum(FaturaID=PedidoID), count(*) from fFaturamento')
chk('status_pedido_x_fatura', "select p.StatusPedido, count(*), sum(f.PedidoID is not null), sum(e.PedidoID is not null), sum(cr.PedidoID is not null) from fPedido p left join fFaturamento f on f.PedidoID=p.PedidoID left join fEntrega e on e.PedidoID=p.PedidoID left join fContasReceber cr on cr.PedidoID=p.PedidoID group by 1")
chk('pedidos_sem_item', 'select count(*) from fPedido p where not exists (select 1 from fItemPedido i where i.PedidoID=p.PedidoID)')
chk('itens_por_pedido', 'select min(n),avg(n),max(n) from (select count(*) n from fItemPedido group by PedidoID)')
chk('receita_fatura_vs_itens', "select count(*), sum(abs(f.ReceitaLiquida - i.v) > 0.05), max(abs(f.ReceitaLiquida - i.v)), sum(abs(f.CMV - i.c) > 0.05), max(abs(f.CMV-i.c)) from fFaturamento f join (select PedidoID, sum(ValorLiquido) v, sum(CustoMercadoria) c from fItemPedido group by PedidoID) i on i.PedidoID=f.PedidoID")
chk('item_valor_vs_qtd_preco', "select count(*), sum(abs(ValorLiquido - Quantidade*PrecoUnitario) > 0.05), max(abs(ValorLiquido - Quantidade*PrecoUnitario)) from fItemPedido")
chk('item_preco_vs_tabela_desc', "select count(*), sum(abs(i.PrecoUnitario - round(pr.PrecoTabela*(1-p.DescontoPercentual),2))>0.05), avg(i.PrecoUnitario/pr.PrecoTabela), avg(1-p.DescontoPercentual) from fItemPedido i join dProduto pr on pr.ProdutoID=i.ProdutoID join fPedido p on p.PedidoID=i.PedidoID")
chk('titulo_vs_fatura', "select count(*), sum(abs(cr.ValorTitulo-f.ReceitaLiquida)>0.01) from fContasReceber cr join fFaturamento f on f.PedidoID=cr.PedidoID")
chk('titulo_cliente_vs_pedido', "select sum(cr.ClienteID<>p.ClienteID) from fContasReceber cr join fPedido p on p.PedidoID=cr.PedidoID")
chk('cr_pagamento_coerencia', "select case when DataPagamento is null then 'sem_data' else 'com_data' end, case when ValorPago=0 then 'pago0' when abs(ValorPago-ValorTitulo)<0.01 then 'integral' else 'parcial' end, count(*) from fContasReceber group by 1,2")
chk('cr_pago_antes_faturamento', "select count(*) from fContasReceber cr join fFaturamento f on f.PedidoID=cr.PedidoID where cr.DataPagamento < f.DataFaturamento")
chk('cr_venc_antes_fatur', "select count(*) from fContasReceber cr join fFaturamento f on f.PedidoID=cr.PedidoID where cr.Vencimento < f.DataFaturamento")
chk('fatura_antes_pedido', "select count(*) from fFaturamento f join fPedido p on p.PedidoID=f.PedidoID where f.DataFaturamento < p.DataPedido")
chk('lag_faturamento_dias', "select min(julianday(f.DataFaturamento)-julianday(p.DataPedido)), avg(julianday(f.DataFaturamento)-julianday(p.DataPedido)), max(julianday(f.DataFaturamento)-julianday(p.DataPedido)) from fFaturamento f join fPedido p using(PedidoID)")
chk('entrega_antes_fatura', "select count(*) from fEntrega e join fFaturamento f using(PedidoID) where e.DataEntrega < f.DataFaturamento")
chk('entrega_antes_pedido', "select count(*) from fEntrega e join fPedido p using(PedidoID) where e.DataEntrega < p.DataPedido")
chk('noprazo_coerencia', "select NoPrazo, sum(DataEntrega<=DataPrometida), sum(DataEntrega>DataPrometida) from fEntrega group by 1")
chk('status_entrega_x_otif', "select StatusEntrega, count(*), sum(NoPrazo=1 and InFull=1), sum(NoPrazo=0), sum(InFull=0) from fEntrega group by 1")
chk('pedido_antes_cadastro_cliente', "select count(*), count(distinct p.ClienteID) from fPedido p join dCliente c using(ClienteID) where p.DataPedido < c.DataCadastro")
chk('pedido_cliente_inativo', "select c.Inativo, count(*), max(p.DataPedido) from fPedido p join dCliente c using(ClienteID) group by 1")
chk('pedido_antes_admissao_vendedor', "select count(*) from fPedido p join dVendedor v using(VendedorID) where p.DataPedido < v.DataAdmissao")
chk('pedido_filial_vs_vendedor_filial', "select sum(p.FilialID<>v.FilialID), count(*) from fPedido p join dVendedor v using(VendedorID)")
chk('pedido_filial_vs_cliente_filial', "select sum(p.FilialID<>c.FilialID), count(*) from fPedido p join dCliente c using(ClienteID)")
chk('pedido_campanha_fora_vigencia', "select count(*), sum(p.DataPedido<c.Inicio or p.DataPedido>c.Fim) from fPedido p join dCampanha c using(CampanhaID)")
chk('devolucao_vs_fatura', "select count(*), sum(d.ValorDevolvido>f.ReceitaLiquida), sum(d.DataDevolucao<f.DataFaturamento), sum(f.PedidoID is null) from fDevolucao d left join fFaturamento f using(PedidoID)")
chk('devolucao_status_pedido', "select p.StatusPedido, count(*) from fDevolucao d join fPedido p using(PedidoID) group by 1")
chk('datas_pos_corte', "select 'fPedido',sum(DataPedido>'2026-10-31') from fPedido union all select 'fFaturamento',sum(DataFaturamento>'2026-10-31') from fFaturamento union all select 'fCompra',sum(DataCompra>'2026-10-31') from fCompra union all select 'fDespesa',sum(DataReferencia>'2026-10-31') from fDespesa union all select 'fMeta',sum(DataReferencia>'2026-10-31') from fMeta union all select 'fOrcamento',sum(DataReferencia>'2026-10-31') from fOrcamento union all select 'fEstoqueMensal',sum(DataReferencia>'2026-10-31') from fEstoqueMensal union all select 'fMovimentoEstoque',sum(DataMovimento>'2026-10-31') from fMovimentoEstoque union all select 'fOcupacaoArmazem',sum(DataReferencia>'2026-10-31') from fOcupacaoArmazem union all select 'fContasPagar_venc',sum(Vencimento>'2026-10-31') from fContasPagar union all select 'fPrevisao',sum(DataReferencia>'2026-10-31') from fPrevisao")
chk('compra_pos_corte_status', "select StatusCompra, count(*) from fCompra where DataCompra>'2026-10-31' group by 1")
chk('cp_sem_pagamento', "select sum(DataPagamento is null), sum(DataPagamento is null and Vencimento<'2026-10-31'), sum(abs(cp.ValorTitulo-c.ValorCompra)>0.01) from fContasPagar cp join fCompra c using(CompraID)")
chk('cp_compra_pos_corte', "select count(*), min(c.DataCompra), max(cp.Vencimento) from fContasPagar cp join fCompra c using(CompraID) where c.DataCompra>'2026-10-31'")
chk('meta_indicadores', "select Indicador, count(*), min(ValorMeta), max(ValorMeta) from fMeta group by 1")
chk('meta_grao_unico', "select count(*) from (select DataReferencia, FilialID, Indicador, count(*) n from fMeta group by 1,2,3 having n>1)")
chk('orc_grao_unico', "select count(*) from (select DataReferencia, FilialID, Conta, count(*) n from fOrcamento group by 1,2,3 having n>1)")
chk('orc_receita_igual_meta_fat', "select count(*), sum(abs(o.ValorOrcado-m.ValorMeta)<0.01) from fOrcamento o join fMeta m on m.DataReferencia=o.DataReferencia and m.FilialID=o.FilialID and m.Indicador='Faturamento' where o.Conta='Receita'")
chk('estoque_200_por_filial_mes', "select min(n), max(n) from (select DataReferencia, FilialID, count(*) n from fEstoqueMensal group by 1,2)")
chk('estoque_ruptura_coerencia', "select Ruptura, sum(SaldoUnidades=0), sum(SaldoUnidades<EstoqueMinimo), count(*) from fEstoqueMensal group by 1")
chk('estoque_grao_dup', "select count(*) from (select DataReferencia, FilialID, ProdutoID, count(*) n from fEstoqueMensal group by 1,2,3 having n>1)")
chk('mov_sinal_coerencia', "select TipoMovimento, sum(QuantidadeAssinada>0), sum(QuantidadeAssinada<0) from fMovimentoEstoque group by 1")
chk('ocup_por_mes', "select min(n), max(n) from (select DataReferencia, count(*) n from fOcupacaoArmazem group by 1)")
chk('ocup_por_filial_mes', "select min(n), max(n), count(*) from (select o.DataReferencia, p.FilialID, count(*) n from fOcupacaoArmazem o join dPosicaoArmazem p using(PosicaoID) group by 1,2)")
chk('ocup_posicao_dup_mes', "select count(*) from (select DataReferencia, PosicaoID, count(*) n from fOcupacaoArmazem group by 1,2 having n>1)")
chk('ocup_status_paletes', "select StatusPosicao, count(*), min(Paletes), max(Paletes) from fOcupacaoArmazem group by 1")
chk('posicoes_por_filial', "select min(n), max(n) from (select FilialID, count(*) n from dPosicaoArmazem group by 1)")
chk('endereco_unico_por_filial', "select count(*) from (select FilialID, EnderecoWMS, count(*) n from dPosicaoArmazem group by 1,2 having n>1)")
chk('cal_continuidade', "select count(*), min(Data), max(Data), julianday(max(Data))-julianday(min(Data))+1 from dCalendario")
chk('cal_diasemana', "select Data, DiaSemana, DiaUtil from dCalendario where Data in ('2024-01-01','2024-01-06','2024-01-07','2026-10-31','2026-11-01')")
chk('cal_diautil_feriado', "select count(*), sum(DiaSemana<=5 and DiaUtil=0), sum(DiaSemana>5 and DiaUtil=1) from dCalendario")
chk('previsao_meses', "select DataReferencia, count(*), sum(DataReferencia in (select Data from dCalendario)) from fPrevisao group by 1")
chk('previsao_vs_meta_jan27', "select count(*) from fMeta where DataReferencia>='2027-01-01'")
chk('despesa_grao', "select min(n),max(n) from (select DataReferencia, FilialID, count(*) n from fDespesa group by 1,2)")
chk('datas_fim_mes', "select 'fDespesa', sum(date(DataReferencia,'+1 day') not like '%-01') from fDespesa union all select 'fMeta', sum(date(DataReferencia,'+1 day') not like '%-01') from fMeta union all select 'fEstoqueMensal', sum(date(DataReferencia,'+1 day') not like '%-01') from fEstoqueMensal union all select 'fMovimentoEstoque', sum(date(DataMovimento,'+1 day') not like '%-01') from fMovimentoEstoque")
chk('item_produto_descontinuado', "select pr.Descontinuado, count(*) from fItemPedido i join dProduto pr using(ProdutoID) group by 1")
chk('margem_negativa_fatura', "select sum(CMV>ReceitaLiquida), count(*) from fFaturamento")
chk('impostos_pct', "select min(Impostos/ReceitaLiquida), avg(Impostos/ReceitaLiquida), max(Impostos/ReceitaLiquida) from fFaturamento")
chk('compras_vs_produtos', "select count(*) from fCompra c join dProduto p using(ProdutoID) where abs(c.ValorCompra/c.Quantidade - p.CustoReferencia)>0.05")
chk('visita_cliente_filial_vend', "select sum(c.FilialID<>v.FilialID), count(*) from fVisitaComercial x join dCliente c using(ClienteID) join dVendedor v using(VendedorID)")
# Reconciliacoes base
REC = {}
REC['receita_cmv_impostos'] = q('select count(*), round(sum(ReceitaLiquida),2), round(sum(CMV),2), round(sum(Impostos),2), round(sum(ReceitaLiquida)-sum(CMV),2), round((sum(ReceitaLiquida)-sum(CMV))/sum(ReceitaLiquida),6) from fFaturamento')
REC['receita_por_ano'] = q("select substr(DataFaturamento,1,4), count(*), round(sum(ReceitaLiquida),2), round(sum(CMV),2) from fFaturamento group by 1")
REC['receita_por_filial'] = q("select p.FilialID, round(sum(f.ReceitaLiquida),2) from fFaturamento f join fPedido p using(PedidoID) group by 1")
REC['pedidos'] = q('select count(*), count(distinct PedidoID) from fPedido')
REC['itens'] = q('select count(*), round(sum(ValorLiquido),2), sum(Quantidade) from fItemPedido')
REC['otif'] = q('select count(*), sum(NoPrazo=1 and InFull=1), round(1.0*sum(NoPrazo=1 and InFull=1)/count(*),6), round(sum(CustoFrete),2) from fEntrega')
REC['devolucao'] = q('select count(*), round(sum(ValorDevolvido),2) from fDevolucao')
REC['despesa_ate_corte'] = q("select round(sum(Valor),2) from fDespesa where DataReferencia<='2026-10-31'")
REC['despesa_total'] = q("select round(sum(Valor),2) from fDespesa")
REC['clientes_com_pedido'] = q('select count(distinct ClienteID) from fPedido')
REC['clientes_com_fatura'] = q('select count(distinct p.ClienteID) from fFaturamento f join fPedido p using(PedidoID)')
REC['receber_aberto'] = q('select round(sum(ValorTitulo-ValorPago),2) from fContasReceber')
json.dump({'pk': R['pk'], 'fk': R['fk'], 'checks': C, 'reconciliacoes': REC}, open(os.path.join(raiz,'testes/resultados/a02_integridade.json'),'w',encoding='utf-8'), ensure_ascii=False, indent=1, default=str)
print('PK falhas:', {k:v for k,v in R['pk'].items() if v})
for f in R['fk']:
    if f['orfaos'] or f['dup_destino']: print('FK', f)
print('FK testadas', len(R['fk']), 'com orfaos', sum(1 for f in R['fk'] if f['orfaos']))
for k,v in C.items(): print(k, v)
for k,v in REC.items(): print('REC', k, v)
